alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

create or replace function public.is_board_member(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_board_editor(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
  );
$$;

create or replace function public.board_is_archived(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.boards b
    where b.id = p_board_id
      and b.is_archived
  );
$$;

create or replace function public.can_write_to_board(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
      and not exists (
        select 1
        from public.boards b
        where b.id = p_board_id
          and b.is_archived
      )
  );
$$;

revoke all on function public.is_board_member(bigint) from public, anon;
revoke all on function public.is_board_editor(bigint) from public, anon;
revoke all on function public.board_is_archived(bigint) from public, anon;
revoke all on function public.can_write_to_board(bigint) from public, anon;

grant execute on function public.is_board_member(bigint) to authenticated, service_role;
grant execute on function public.is_board_editor(bigint) to authenticated, service_role;
grant execute on function public.board_is_archived(bigint) to authenticated, service_role;
grant execute on function public.can_write_to_board(bigint) to authenticated, service_role;

create policy "board_members_select_own_boards"
on public.boards
for select
to authenticated
using (public.is_board_member(id));

create policy "cards_select_board_members"
on public.cards
for select
to authenticated
using (public.is_board_member(board_id));

create policy "cards_insert_editor_writeable_board"
on public.cards
for insert
to authenticated
with check (
  public.is_board_editor(board_id)
  and public.can_write_to_board(board_id)
  and assignee_id is not distinct from auth.uid()
);

create policy "cards_update_editor_writeable_board"
on public.cards
for update
to authenticated
using (
  public.is_board_editor(board_id)
  and public.can_write_to_board(board_id)
)
with check (
  public.is_board_editor(board_id)
  and public.can_write_to_board(board_id)
);

create policy "cards_delete_editor_writeable_board"
on public.cards
for delete
to authenticated
using (
  public.is_board_editor(board_id)
  and public.can_write_to_board(board_id)
);

revoke all on public.boards from anon;
revoke all on public.board_members from anon;
revoke all on public.cards from anon;

revoke insert, update, delete on public.boards from authenticated;
revoke insert, update, delete on public.board_members from authenticated;

grant select on public.boards to authenticated;
grant select on public.board_members to authenticated;
grant select, insert, update, delete on public.cards to authenticated;

grant all on public.boards to service_role;
grant all on public.board_members to service_role;
grant all on public.cards to service_role;

revoke all on sequence public.cards_id_seq from anon;
grant usage, select on sequence public.cards_id_seq to authenticated, service_role;
