create schema private;

grant usage on schema private to authenticated;

create function private.is_member(bid bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.board_members m where m.board_id = bid and m.user_id = auth.uid())
$$;

create function private.is_editor(bid bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.board_members m where m.board_id = bid and m.user_id = auth.uid() and m.role = 'editor')
$$;

create function private.board_active(bid bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select coalesce((select b.is_archived = false from public.boards b where b.id = bid), false)
$$;

alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

create policy boards_select on public.boards
  for select to authenticated
  using (private.is_member(id));

create policy board_members_select on public.board_members
  for select to authenticated
  using (user_id = auth.uid() or private.is_member(board_id));

create policy cards_select on public.cards
  for select to authenticated
  using (private.is_member(board_id));

create policy cards_insert on public.cards
  for insert to authenticated
  with check (private.is_editor(board_id) and private.board_active(board_id));

create policy cards_update on public.cards
  for update to authenticated
  using (private.is_editor(board_id) and private.board_active(board_id))
  with check (private.is_editor(board_id) and private.board_active(board_id));

create policy cards_delete on public.cards
  for delete to authenticated
  using (private.is_editor(board_id) and private.board_active(board_id));
