create or replace function public.is_unit_resident(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.residents r
    where r.unit_id = p_unit_id
      and r.user_id = auth.uid()
  );
$$;

create or replace function public.is_building_staff(p_building_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.building_staff s
    where s.building_id = p_building_id
      and s.user_id = auth.uid()
  );
$$;

create or replace function public.can_see_request(p_request_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.requests r
    join public.units u on u.id = r.unit_id
    where r.id = p_request_id
      and (public.is_unit_resident(r.unit_id) or public.is_building_staff(u.building_id))
  );
$$;

create or replace function public.prevent_request_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.created_by is distinct from old.created_by
     or new.description is distinct from old.description then
    raise exception 'Only request status can be updated';
  end if;

  if new.status is distinct from old.status then
    if old.status not in ('open', 'in_progress') then
      raise exception 'Cannot change status of a done request';
    end if;
    if new.status not in ('in_progress', 'done') then
      raise exception 'Invalid status transition';
    end if;
  end if;

  return new;
end;
$$;

create trigger requests_prevent_update
before update on public.requests
for each row execute function public.prevent_request_update();

create policy units_select on public.units
for select to authenticated
using (public.is_unit_resident(id) or public.is_building_staff(building_id));

create policy residents_select on public.residents
for select to authenticated
using (user_id = auth.uid());

create policy building_staff_select on public.building_staff
for select to authenticated
using (user_id = auth.uid());

create policy requests_select on public.requests
for select to authenticated
using (public.is_unit_resident(unit_id) or public.is_building_staff(
  (select u.building_id from public.units u where u.id = requests.unit_id)
));

create policy requests_insert on public.requests
for insert to authenticated
with check (
  created_by = auth.uid()
  and status = 'open'
  and public.is_unit_resident(unit_id)
);

create policy request_photos_select on public.request_photos
for select to authenticated
using (public.can_see_request(request_id));

create policy request_photos_insert on public.request_photos
for insert to authenticated
with check (public.can_see_request(request_id));

