  )
);

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_highest numeric;
  v_increment numeric;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'Auction not found';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'Cannot bid on your own auction';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  if v_auction.highest_bid is null then
    if p_amount < v_auction.starting_price then
      raise exception 'Bid must be at least the starting price';
    end if;
    v_highest := p_amount;
  else
    if p_amount <= v_auction.highest_bid then
      raise exception 'Bid must be higher than the current highest bid';
    end if;
    v_increment := v_auction.min_increment;
    if p_amount < v_auction.highest_bid + v_increment then
      raise exception 'Bid must be at least % higher than the current highest bid', v_increment;
    end if;
    v_highest := p_amount;
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_uid, p_amount);

  update public.auctions
  set highest_bid = v_highest,
      highest_bidder = v_uid
  where id = p_auction_id;

  return v_highest;
end;
$$;

revoke all on public.auctions from anon, authenticated;
revoke all on public.bids from anon, authenticated;
revoke all on sequence public.bids_id_seq from anon, authenticated;

grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;
grant usage, select on sequence public.bids_id_seq to authenticated;

grant all on public.auctions to service_role;
grant all on public.bids to service_role;
grant usage, select on sequence public.bids_id_seq to service_role;

revoke all on function public.place_bid(bigint, numeric) from public, anon;
grant execute on function public.place_bid(bigint, numeric) to authenticated, service_role;
