  on public.bids
  for select
  to authenticated
  using (
    bidder_id = auth.uid()
    or exists (
      select 1
      from public.auctions a
      where a.id = bids.auction_id
        and a.seller_id = auth.uid()
    )
  );

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_highest numeric;
  v_inc numeric;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  select *
    into v_auction
    from public.auctions
   where id = p_auction_id
   for update;

  if not found then
    raise exception 'auction % does not exist', p_auction_id;
  end if;

  if v_auction.seller_id = v_user then
    raise exception 'seller cannot bid on own auction';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.highest_bid is null then
    if p_amount < v_auction.starting_price then
      raise exception 'bid % is below the starting price', p_amount;
    end if;
    v_highest := p_amount;
  else
    v_inc := v_auction.min_increment;
    if p_amount < v_auction.highest_bid + v_inc then
      raise exception 'bid % is below the minimum increment', p_amount;
    end if;
    v_highest := p_amount;
  end if;

  update public.auctions
     set highest_bid = v_highest,
         highest_bidder = v_user
   where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_user, p_amount)
  returning amount
    into v_highest;

  return v_highest;
end;
$$;

revoke all on public.auctions from anon, authenticated;
revoke all on public.bids from anon, authenticated;
revoke all on sequence public.bids_id_seq from anon, authenticated;

grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;
grant usage, select on sequence public.bids_id_seq to authenticated;

grant execute on function public.place_bid(bigint, numeric) to authenticated;

grant all on public.auctions to service_role;
grant all on public.bids to service_role;
grant all on sequence public.bids_id_seq to service_role;
grant execute on function public.place_bid(bigint, numeric) to service_role;
