alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

-- R5: anonymous visitors get nothing
revoke all on public.classes from anon;
revoke all on public.class_spots from anon;

-- R5: authenticated can read only
grant select on public.classes to authenticated;
grant select on public.class_spots to authenticated;

-- R5: no writes are granted to anon or authenticated, so they are denied

-- R1: signed-in users can see every class
create policy "classes_select_authenticated"
  on public.classes
  for select
  to authenticated
  using (true);

-- R1: members see their own spots, instructors see every spot in their classes
create policy "class_spots_select_own_or_instructor"
  on public.class_spots
  for select
  to authenticated
  using (
    user_id = auth.uid()
    or exists (
      select 1
      from public.classes c
      where c.id = class_spots.class_id
        and c.instructor_id = auth.uid()
    )
  );

-- R2: join as enrolled only while room exists, otherwise only waitlisted
create policy "class_spots_insert_join_with_capacity"
  on public.class_spots
  for insert
  to authenticated
  with check (
    user_id = auth.uid()
    and (
      (status = 'enrolled'
        and exists (
          select 1
          from public.class_spots s
          where s.class_id = class_spots.class_id
            and s.status = 'enrolled'
          group by s.class_id
          having count(*) < (
            select c.capacity
            from public.classes c
            where c.id = s.class_id
          )
        ))
      or status = 'waitlisted'
    )
  );

-- R3 / R4: members move their own waitlist to enrolled only when room exists;
-- members delete their own spot; instructors remove any spot from their classes
create policy "class_spots_update_own_waitlist_to_enrolled"
  on public.class_spots
  for update
  to authenticated
  using (user_id = auth.uid() and status = 'waitlisted')
  with check (user_id = auth.uid() and status = 'enrolled');

create policy "class_spots_update_member_or_instructor"
  on public.class_spots
  for update
  to authenticated
  using (
    user_id = auth.uid()
    or exists (
      select 1
      from public.classes c
      where c.id = class_spots.class_id
        and c.instructor_id = auth.uid()
    )
  )
  with check (
    user_id = auth.uid()
    or exists (
      select 1
      from public.classes c
      where c.id = class_spots.class_id
        and c.instructor_id = auth.uid()
    )
  );

create policy "class_spots_delete_own_or_instructor"
  on public.class_spots
  for delete
  to authenticated
  using (
    user_id = auth.uid()
    or exists (
      select 1
      from public.classes c
      where c.id = class_spots.class_id
        and c.instructor_id = auth.uid()
    )
  );

-- R3: no column of class_spots may change except the status field of a spot
-- belonging to the acting user, and only from waitlisted to enrolled.
create or replace function public.class_spots_enforce_update()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if current_user = 'service_role'
     or current_user in ('postgres', 'supabase_admin') then
    return new;
  end if;

  if new.class_id is distinct from old.class_id
     or new.user_id is distinct from old.user_id then
    raise exception 'class_id and user_id of a class_spot cannot be changed';
  end if;

  if new.status is distinct from old.status then
    if new.user_id is distinct from auth.uid() then
      raise exception 'only the owner can change a spot status';
    end if;
    if old.status = 'enrolled' then
      raise exception 'cannot change status from enrolled';
    end if;
    if old.status = 'waitlisted' and new.status <> 'enrolled' then
      raise exception 'waitlisted spot can only be moved to enrolled';
    end if;
  end if;

  return new;
end;
$$;

create trigger class_spots_enforce_update
  before update on public.class_spots
  for each row
  execute function public.class_spots_enforce_update();

-- R6: service role keeps full access
grant all on public.classes to service_role;
grant all on public.class_spots to service_role;
