grant all on public.classes to service_role;
grant all on public.class_spots to service_role;

-- Helper: count enrolled members of a class (used by R2)
create or replace function public.class_enrolled_count(p_class_id bigint)
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select count(*)::integer
  from public.class_spots
  where class_id = p_class_id
    and status = 'enrolled';
$$;

revoke all on function public.class_enrolled_count(bigint) from public;
grant execute on function public.class_enrolled_count(bigint) to authenticated, service_role;

-- R1: signed-in users see every class
create policy classes_select_authenticated
  on public.classes
  for select
  to authenticated
  using (true);

-- R1 + R4: members see their own spots; instructors see all spots of their classes
create policy class_spots_select_self_or_instructor
  on public.class_spots
  for select
  to authenticated
  using (
    user_id = auth.uid()
    or exists (
      select 1
      from public.classes c
      where c.id = class_spots.class_id
        and c.instructor_id = auth.uid()
    )
  );

-- R2: join a class as themselves, only if room or as waitlist
create policy class_spots_insert_join_as_self
  on public.class_spots
  for insert
  to authenticated
  with check (
    user_id = auth.uid()
    and (
      status = 'enrolled'
      and public.class_enrolled_count(class_id) < (
        select c.capacity from public.classes c where c.id = class_id
      )
      or status = 'waitlisted'
    )
  );

-- R3 + R4: move own waitlisted -> enrolled (room only), or delete own spot
create policy class_spots_update_own_waitlist_to_enrolled
  on public.class_spots
  for update
  to authenticated
  using (
    user_id = auth.uid()
    and status = 'waitlisted'
  )
  with check (
    user_id = auth.uid()
    and status = 'enrolled'
    and public.class_enrolled_count(class_id) < (
      select c.capacity from public.classes c where c.id = class_id
    )
  );

create policy class_spots_delete_own
  on public.class_spots
  for delete
  to authenticated
  using (user_id = auth.uid());

-- R3: nothing else about a spot can change (status, class_id, user_id are
-- immutable except the two rules above)
create or replace function public.class_spots_guard_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;

  if new.class_id is distinct from old.class_id
     or new.user_id is distinct from old.user_id then
    raise exception 'class_id and user_id cannot be changed';
  end if;

  if new.status is distinct from old.status then
    if new.status = 'enrolled'
       and old.status = 'waitlisted'
       and current_user = auth.uid() then
      if public.class_enrolled_count(new.class_id) >= (
        select c.capacity from public.classes c where c.id = new.class_id
      ) then
        raise exception 'class is full';
      end if;
    else
      raise exception 'invalid status transition';
    end if;
  end if;

  return new;
end;
$$;

create trigger class_spots_guard_update
  before update on public.class_spots
  for each row
  execute function public.class_spots_guard_update();

revoke all on function public.class_spots_guard_update() from public;
grant execute on function public.class_spots_guard_update() to authenticated, service_role;
